const n=x=>Number(x).toLocaleString('en-US');
export function betSizing(options,pot,currentBet,player,value=options.min){
 const target=Number(value),valid=value!==''&&Number.isInteger(target)&&target>=options.min&&target<=options.max&&options.canRaise;
 const clamp=x=>Math.min(options.max,Math.max(options.min,Math.round(x)));
 const presets=[{label:'Min',value:options.min},...[['⅓ pot',1/3],['½ pot',.5],['Pot',1]].map(([label,fraction])=>({label,value:clamp(currentBet+(pot+options.call)*fraction)})),{label:'All-in',value:options.max}];
 return {target,valid,extra:valid?target-player.bet:null,remaining:valid?player.stack-(target-player.bet):null,label:`${currentBet?'Raise to':'Bet'} ${Number.isFinite(target)?n(target):'—'}`,presets};
}
export function betPanelHTML(options,pot,currentBet,player){if(!options.canRaise)return '';const s=betSizing(options,pot,currentBet,player);return `<div class="bet-panel" id="raise-panel" hidden><div class="bet-panel-heading"><label for="raise-amount">${currentBet?'Raise to':'Bet amount'}<small>Total chips this betting round</small></label><div class="bet-input"><input id="raise-amount" type="number" inputmode="numeric" min="${options.min}" max="${options.max}" step="1" value="${options.min}" aria-describedby="bet-impact"><span>chips</span></div></div><input id="raise-slider" class="bet-slider" aria-label="Bet size" type="range" min="${options.min}" max="${options.max}" step="1" value="${options.min}"><div class="bet-presets">${s.presets.map(p=>`<button type="button" data-bet-size="${p.value}"><strong>${p.label}</strong><span>${n(p.value)}</span></button>`).join('')}</div><p id="bet-impact" class="bet-impact" aria-live="polite">Add <strong>${n(s.extra)}</strong> more · <strong>${n(s.remaining)}</strong> left${s.remaining===0?' · ALL-IN':''}</p><p class="bet-explanation">Already in: ${n(player.bet)} chips.</p><div class="bet-confirm-row"><button type="button" data-bet-close>Cancel</button><button type="button" class="primary" data-action="raise">${s.label}</button></div></div>`;}
export function updateBetPanel(root,options,pot,currentBet,player,source){const input=root.querySelector('#raise-amount'),slider=root.querySelector('#raise-slider'),button=root.querySelector('[data-action="raise"]');if(!input||!button)return;if(source?.id==='raise-slider')input.value=source.value;const s=betSizing(options,pot,currentBet,player,input.value);button.textContent=s.label;button.disabled=!s.valid;if(s.valid)slider.value=s.target;root.querySelector('#bet-impact').innerHTML=s.valid?`Add <strong>${n(s.extra)}</strong> more · <strong>${n(s.remaining)}</strong> left${s.remaining===0?' · ALL-IN':''}`:`Choose a whole-chip total from ${n(options.min)} to ${n(options.max)}.`;}

export function actionControlsHTML(options,pot,currentBet,player){return `<div class="action-buttons basic-actions"><button data-action="fold">Fold</button><button class="primary" data-action="${options.canCheck?'check':'call'}">${options.canCheck?'Check · free':'Call '+n(options.call)}</button><button data-bet-toggle aria-expanded="false" aria-controls="raise-panel" ${options.canRaise?'':'disabled'}>${currentBet?'Raise':'Bet'} <span aria-hidden="true">⌄</span></button></div>${betPanelHTML(options,pot,currentBet,player)}`;}
export function toggleBetPanel(root,target){const open=target.closest('[data-bet-toggle]'),close=target.closest('[data-bet-close]');if(!open&&!close)return false;const panel=root.querySelector('#raise-panel'),button=root.querySelector('[data-bet-toggle]');if(!panel)return true;panel.hidden=close?true:!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)root.querySelector('#raise-amount').focus({preventScroll:true});return true;}
